\begin{equation}  
    \label{eq:problem}  
    \min_{x \in \text{dom}\,\varphi} \varphi(x): = f(x) + h(F(x)) + \sum_{i=1}^{n_{\text{block}}} g_i(x^i), 
\end{equation}

where \( F(x): = (F_1(x), \cdots, F_m(x)) \) and \( f \) are nonlinear differentiable functions defined on \(\text{dom}\,\varphi\). The functions \( g_i \) are proper, lower semicontinuous (lsc), and convex.
They may be nonsmooth, while \( h \) is a smooth and convex function. Here, \( n = \sum_{i=1}^{n_{\text{block}}} n_i \), \( x^i \in \mathbb{R}^{n_i} \), and \( g(x) := \sum_{i=1}^{n_{\text{block}}} g_i(x^i) \).\footnote{Note that, from the point of view of general theory, $f$ is superfluous, and can be subsumed by $h \circ F$. It is, however, practical to explicitly include it for our application examples.}


In what follows, we use $\| \cdot \|$ to denote the 2-norm of a vector or a matrix, respectively. Let $n = \sum_{i=1}^{n_\text{block}} n_i$. For a differentiable function $\phi: \mathbb{R}^n \to \mathbb{R}$, we denote its gradient with respect to the $i^{\text{th}}$ block at a point $x$ as $\nabla_i \phi(x) \in \mathbb{R}^{n_i}$, for any $i \in \{1, \dots, n_\text{block}\}$. For a differentiable vector function $F: \mathbb{R}^n \to \mathbb{R}^m$, we denote its Jacobian with respect to the $i^{\text{th}}$ block at a given point $x$ as $\nabla_i F(x) \in \mathbb{R}^{m \times n_i}$. We define the distance from a point $x$ to a set $A$ as $\dist(x, A) := \min_{a \in A} \| x - a \|$. Furthermore, for a proper, lower semicontinuous (lsc) function $g: \mathbb{R}^n \to \mathbb{R}$, we use $\partial g(x)$ to refer to its Mordukhovich (aka.~limiting) subdifferential at a point $x$, and $\partial^{\infty} g(x)$ to refer to the horizon subdifferential.
This, instead of the plain convex subdifferential, is required due to the nonconvexity of $h \circ F$ and hence the composite objective $\phi$.
For more details about the subdifferential of nonsmooth functions, we refer to \cite{rockafellar2009variational}. In the following, we say that a point \( x^* \in \mathbb{R}^n \) is a stationary point of problem~\eqref{eq:problem} if \( 0 \in \partial \varphi(x^*) \). Moreover, for \( \epsilon > 0 \), \( x^* \) is said to be an \( \epsilon \)-stationary point of problem \eqref{eq:problem} if \( \dist\left( 0, \partial \varphi(x^*) \right) \leq \epsilon \).


\begin{assumption}\label{ass:1}
    \begin{enumerate} %[itemsep=1pt]
    \item Given a compact set $\mathcal{C}$, the gradients of $f$ and $F_j$ for $j=1:m$ are block coordinate-wise Lipschitz continuous in $\mathcal{C}$, i.e., $\forall i\in \{1,\cdots,n_{\text{block}}\},\;x,y\in \mathcal{C}$
        \begin{align*}
        \|\nabla_i f(x) - \nabla_if(y)\|\leq L^{f}_i \|x - y\|,
        \|\nabla_i F_j(x) - \nabla_i F_j(y)\|\leq L^{F_j}_i \|x - y\|.
        \end{align*}
    \item $h$ is convex, differentiable with Lipschitz gradient
        \begin{align*}
            \|\nabla h(u) - \nabla h(v)\|\leq L_{h} \|u - v\|,\;\forall \;u,v\in\mathbb{R}^{m}.
        \end{align*}
    \item Each $g_i$ is a proper, lsc, convex function.
    \item $ \forall x\in\mathcal{C}$, $u\in\mathbb{R}^m$ and $i\in\{1,\cdots,n_{\text{block}}\}$ we have
        $
             f(x) \geq f^*,\; h(u)\geq h^*,\;g_i(x) \geq g^*.% \varphi(x) \geq \varphi^*,\;
        $
    \end{enumerate}
\end{assumption}

In the sequel, for all $i=\{1,\ldots,n_{\text{block}}\}$, $\bar{x}^i, s\in\mathbb{R}^{n_i}$ and $\bar{x}\in\mathbb{R}^n$, we denote
\begin{align*}
    &l^i_f(s;\bar{x}^i)
    :=
    f(\bar{x})+\langle\nabla_i f(\bar{x}),s-\bar{x}^i\rangle,\quad
    l^i_F \big(s;\bar{x}^i \big):=F(\bar{x})+ \nabla_i F(\bar{x}) \big(s-\bar{x}^i \big),\\
    &\quad\text{and}\quad
    \bar{\varphi}^i(s;\bar{x}) = l^i_f \big( s;\bar{x}^i \big)+ h \big( l^i_F(s;\bar{x}^i) \big) + g_i(s).
\end{align*}

\begin{algorithm*}[ht]
\caption{Monotone LiBCoD }
\label{alg:libcod}

\KwIn{$x_0$, $\beta_1 \geq \frac{\beta_{\min}}{2}>0$, $p_{\min} \in (0,1)$}
Set $k = 0$

\While{termination criterion not satisfied}{
  Pick a random index $i_k \in \{1,\cdots,n_{\text{block}}\}$ with probability $p_{i_k} \geq p_{\min}$\:

  \Repeat(
    %\tcp*[f]{\label{line:dec_mon} $\varphi(x_{k+1}) \leq  \varphi(x_k) - \frac{\beta_{k+1}}{2}\|x_{k+1} - x_k\|^{2}$}
  ){
    \textcolor{blue}{$\varphi(x_{k+1}) \leq  \varphi(x_k) - \frac{\beta_{k+1}}{2}\|x_{k+1} - x_k\|^{2}$}
  }{
    $\beta_{k+1} := 2\beta_{k+1}$ \label{line:lin_search}

    $s_{k+1} := \arg\min\limits_{s \in \mathbb{R}^{n_{i_k}}} \resizebox{!}{2ex}{$\langle\nabla_{i_k} f(x_k),s-x_k^{i_k}\rangle + h\left(F(x_k)+\langle\nabla_{i_k} F(x_k),s-x_k^{i_k}\rangle\right) + g_{i_k}(s) + \frac{\beta_{k+1}}{2}\|s - x^{i_k}\|^2$}$ 
    %$s_{k+1} := \arg\min\limits_{s \in \mathbb{R}^{n_{i_k}}} \langle\nabla_{i_k} f(x_k),s-x_k^{i_k}\rangle+ h\left(F(x_k)+\langle\nabla_{i_k} F(x_k),s-x_k^{i_k}\rangle\right) + g_{i_k}(s) + \frac{\beta_{k+1}}{2}\|s - x^{i_k}\|^2$ \label{line:libcod:subprob}

    $x^{i_k}_{k+1} := s_{k+1}$ and $x^{i}_{k+1} = x_k^i$ for $i\neq i_k$
  }

  Set $k=k+1$ and $\beta_{k+1} = \max\left\{\frac{\beta_{k}}{4},\frac{\beta_{\min}}{2}\right\}$
}
\end{algorithm*}

$
\Delta{x}_{k+1} := x_{k+1} - x_k .
$


\begin{equation} \label{eq:beta_cond}
    \beta_{k+1} \geq L^f_{i_k} + L^F_{i_k}\sqrt{2 L_h}\sqrt{\varphi(x_k)- \varphi^*},
\end{equation}

where $\varphi^* = h^* + f^* + g^*$, then the process in Monotone LiBCoD \ref{alg:libcod}, is well defined. 


Note that in Monotone LiBCoD \ref{alg:libcod}, $\beta_{k+1}$ is always upper bounded by
\begin{equation}
\label{bar_gamma}
    \bar{\beta} := \sup_{k\geq 1}\beta_k \leq 2 \left(L^f+ L^F\sqrt{2L_h}\sqrt{\varphi(x_0)-\varphi^*}\right),
\end{equation}

 where $L^f:=\max_{i\in\{1, \ldots, n_{\text{block}}\}} L^f_{i}$  and  $L^F:=\max_{i\in\{1, \ldots, n_{\text{block}}\}} L^F_{i}$.

