statement.raw_tex:
\begin{theorem}[Iteration complexity]
    \label{thm:convergence:monotone}
    Let $(x_k)_{k\geq 0}$ be generated by Monotone LiBCoD \ref{alg:libcod}. If \cref{ass:1} holds on a compact set to which the iterates belong, then, for any $\epsilon>0$,  Monotone LiBCoD \ref{alg:libcod} yields, in expectation, an $\epsilon$-stationary point of \eqref{eq:problem}, i.e.,
    \[
     \E\left[\dist(0, \partial\varphi(x_{k+1})) \right] \leq \epsilon,
    \]
%  \textcolor{red}{where $\partial \varphi(x)$ denotes the Mordukhovich (aka.~limiting) subdifferential of $\varphi$ at $x$,}
    within  
    \begin{gather*}
        \left(\frac{4\left(L^f+ L^F \sqrt{2L_h} \sqrt{\varphi(x_0)- \varphi^*} + \bar{\beta}\right)^2}{p_{\min} \beta_{\min} \epsilon^2} + \frac{2 L_h M^F L^F}{p_{\min} \beta_{\min} \epsilon} \right)\left(\varphi(x_0) - \varphi^*\right)
    \end{gather*}  
    iterations.
\end{theorem}

