proof.raw_tex:
\begin{lemma}
    \label{lemma1}
    Let $(x_k)_{k\geq 0}$ be generated by Monotone LiBCoD \ref{alg:libcod}. If \cref{ass:1} holds on a compact set $\mathcal{C}$ containing the iterates, and $\beta_{k+1}$ satisfies \eqref{eq:beta_cond}, then
    \begin{align}
        \label{decrease}
         \varphi(x_{k+1}) \leq  \varphi(x_{k}) - \frac{\beta_{k+1}}{2} \|x_{k+1} - x_k\|^2.
    \end{align}
\end{lemma}

\begin{proof}
    This proof follows a reasoning similar to that in \cite{marumo2024accelerated} [Lemma 3.1], adapted to the coordinate descent framework with an additional smooth function $f$.  
    %\seb{it would be nice to repeat there some of the definitions (for better readability)}
    %\seb{it seems the proof (for the second term) follows exactly \cite{marumo2024accelerated}? maybe mention this here, and explain the differences}
    Note that the subproblem's objective function
    \[
        q(s) := \bar{\varphi}^{i_k}(s;x_k)+\frac{\beta_{k+1}}{2}\|s-x^i_k\|^2,
    \]
    By the strong convexity of this objective and $s_{k+1}$ being a minimiser, i.e., $0 \in \partial q(s_{k+1})$,
    \[
        q(x_k^i)
        \ge
        q(s_{k+1}) + \frac{\beta_{k+1}}{2}\|s_{k+1}-x^i_k\|^2.
    \]
    Hence, expanding $q$,
    % is strongly convex with a strong convexity constant $\beta_{k+1}$, then,
    % \[
    %    \bar{\varphi}^{i_k}(x_k;x_k)+\frac{\beta_{k+1}}{2}\|x^i_k-x^i_k\|^2 \geq \bar{\varphi}^{i_k}(s_{k+1};x_k)+\frac{\beta_{k+1}}{2}\|s_{k+1}-x^i_k\|^2 + \frac{\beta_{k+1}}{2}\norm{x_{k+1} - x_k}^2 
    % \]
    % combining this with the optimality of $s_{k+1}$,  
    the fact that $\bar{\varphi}^{i_k}(x^{i_k}_k;x_k)=\varphi(x_{k}) - \sum_{i\neq i_k} g_i(x^i_{k})$ and making use of the fact that $x^i_{k+1} = x^i_k$ for $i\neq i_k$, we get
    \begin{equation} \label{initial_decrease}
        \bar{\varphi}^{i_k}(s_{k+1};x_k)\leq \varphi(x_{k}) - \sum_{i\neq i_k} g_i(x^i_{k+1}) -\beta_{k+1}\|x_{k+1}-x_k\|^2.
    \end{equation}
%    \seb{is it $\frac{\beta_{k+1}}{2}$? \textcolor{red}{just $\beta_{k+1}$ since we use the strong convexity of $\bar{\varphi}^{i_k}(\cdot;x_k)$}}%
%    \seb{I still don't see this. Strong convexity gives $\varphi(x) \geq \varphi(s_{k+1}) + \frac{\beta}{2} \| x - s_{k+1}\|^2$ ? \textcolor{red}{ It is \(\varphi(x) + \frac{\beta}{2}\|x - x_k\|^2\) that is strongly convex, whereas \(\varphi(x)\) is not. Thus, we have:
% \[
% \left(\varphi(s) + \frac{\beta}{2} \|s - x_{k}\|^2\right) \geq \left(\varphi(s_{k+1}) + \frac{\beta}{2} \|s_{k+1} - x_{k}\|^2\right) + \frac{\beta}{2} \|s_{k+1} - x_{k}\|^2.
% \]
% %%SEB:
% ok, tricky; 
% } }%
    Furthermore, since \( f \) has a block Lipschitz gradient with a Lipschitz constant \( L_{i_k}^f \), it follows that \cite{nesterov2018lectures}
        \begin{equation}
        \label{smooth_object}
        f(x_{k+1}) - l_f^{i_k}(s_{k+1};x_k) \leq \frac{L^f_{i_k}}{2}\|x_{k+1}-x_k\|^2.
    \end{equation}
    %\seb{can you add a reference to the equation that you are using? (also it would help to remind the readers of the definition of $l_f$)
    %why is there no term with $\nabla f$ ? (a similar equation is also used in (14) below). $s_{k+1}$ is not a minimizer of $f$}
     Moreover, since \( h \) has a Lipschitz gradient with a Lipschitz constant \( L_h \), we have
    \begin{equation}
    \label{decrease_feasib}
    \begin{split}
         h(F(x_{k+1}))& -  h(l^{i_k}_F(s_{k+1};x_k)) 
        \\
        &\leq   \langle \nabla h \left( l^{i_k}_F(s_{k+1};x_k)\right), F(x_{k+1})-l^{i_k}_F(s_{k+1};x_k) \rangle \\
        \MoveEqLeft[-1] + \frac{L_h}{2}\|F(x_{k+1})-l^{i_k}_F(s_{k+1};x_k)\|^2 
        \\
        & \leq \left\|\nabla h \left( l^{i_k}_F(s_{k+1};x_k)\right)\right\| \|F(x_{k+1})-l^{i_k}_F(s_{k+1};x_k) \|\\
        \MoveEqLeft[-1] + \frac{L_h}{2}\|F(x_{k+1})-l^{i_k}_F(s_{k+1};x_k)\|^2 
        \\
        &\overset{\text{Ass. } \ref{ass:1}}{\leq} \left\|\nabla h \left( l^{i_k}_F(s_{k+1};x_k)\right)\right\|  \frac{L^F_{i_k}}{2}\|\Delta x_{k+1}\|^2 + \frac{L_h}{2} \left(\frac{L^F_{i_k}}{2}\|\Delta x_{k+1}\|^2\right)^2. 
    \end{split}
    \end{equation}
    Using the Young's inequality $2\sqrt{a b} - a \leq b$ for any $a, b \geq 0$, and the following relation for $u =l^{i_k}_F(s_{k+1};x_k) \in \mathbb{R}^m$, with $v = u - \frac{1}{L_h} \nabla h(u)$
    \[
        h^* - h(u) \leq h(v) - h(u)
        \leq \langle \nabla h(u), v - u \rangle + \frac{L_h}{2} \norm{v - u}^2 = -\frac{1}{2L_h} \norm{\nabla h(u)}^2,
    \]
    we bound
    \begin{equation}
        \label{bound_grad_norm_squared}
        \begin{split}
            &
            \left\|\nabla h \left( l^{i_k}_F(s_{k+1};x_k)\right)\right\| - \frac{ \beta_{k+1} - L^f_{i_k}}{2L^F_{i_k}} \leq  \frac{L^F_{i_k}}{ 2(\beta_{k+1} - L^f_{i_k})}    \left\|\nabla h \left( l^{i_k}_F(s_{k+1};x_k)\right)\right\|^2
            \\
            &
            \leq
            \frac{L^F_{i_k}L_h}{ \beta_{k+1} - L^f_{i_k}} \left( h(l^{i_k}_F(s_{k+1};x_k)) - h^*  \right)
            %\\
            %&
            =
            \frac{L^F_{i_k}L_h}{ \beta_{k+1} - L^f_{i_k}}
            \\
            \MoveEqLeft[-4]
            \left( \bar{\varphi}^{i_k}(s_{k+1};x_k) - h^* - g_{i_k}(s_{k+1})- f(x_{k+1}) + f(x_{k+1}) - l_f^{i_k}(s_{k+1};x_k)  \right)
            \\
            &
            \overset{\eqref{initial_decrease}, \eqref{smooth_object}}{\leq}
            \frac{L^F_{i_k} L_h}{\beta_{k+1} - L^f_{i_k}} \left( \varphi(x_k) - \varphi^* - \frac{2\beta_{k+1} - L^F_{i_k}}{2}\|\Delta x_{k+1}\|^2 \right)
            \\
            &
            \leq
            \frac{L^F_{i_k} L_h}{\beta_{k+1} - L^f_{i_k}} \left( \varphi(x_k) - \varphi^*\right) - L^F_{i_k} L_h\|\Delta x_{k+1}\|^2
            \\
            &
            \overset{\eqref{eq:beta_cond}}{\leq}\frac{\beta_{k+1}-L^f_{i_k}}{2L^F_{i_k}} - L^F_{i_k} L_h\|\Delta x_{k+1}\|^2,
        \end{split}
    \end{equation}
    where third inequality follows from the definition of $\bar{\varphi}^{i_k}$. Moreover, Using \eqref{bound_grad_norm_squared} in \eqref{decrease_feasib}, we deduce that
    \begin{equation}
        \label{to_use_next}
        \begin{split}
                    h\left(F(x_{k+1})\right) &- h\left(l^{i_k}_F(x_{k+1};x_k) \right)\\
        & \leq
        \frac{\beta_{k+1}-L^f_{i_k}}{2} \|\Delta x_{k+1}\|^2 - \left(\frac{L_h (L^F_{i_k})^2}{2} - \frac{L_h (L^{F}_{i_k})^2}{8} \right) \|\Delta x_{k+1}\|^4
        \\
        &=
        \frac{\beta_{k+1}-L^f_{i_k}}{2} \|\Delta x_{k+1}\|^2-  \frac{3 L_h (L^{F}_{i_k})^2}{8}  \|\Delta x_{k+1}\|^4.
        \end{split}
    \end{equation}
    Moreover, we have
    \begin{align*}
    \begin{split}
        \varphi(x_{k+1}) -\sum_{i\neq i_k} g_i(x^i_{k+1}) - \bar{\varphi}^{i_k}(s_{k+1};x_k)
        &=
        f(x_{k+1}) - l^{i_k}_f(s_{k+1};x_k) + h(F(x_{k+1}))\\
        \MoveEqLeft [-1] - h(l^{i_k}_F(x_{k+1};x_k)).
    \end{split}
    \end{align*}
    Using  \eqref{smooth_object} and \eqref{to_use_next} in the previous relation, it follows that
    \[
        \varphi(x_{k+1}) \leq \bar{\varphi}^{i_k}(s_{k+1};x_k) + \sum_{i\neq i_k} g_i(x^i_{k+1}) + \frac{\beta_{k+1}}{2} \|\Delta x_{k+1}\|^2.
    \]
    Finally, using \eqref{initial_decrease}, we get
    \begin{align*}
        \varphi(x_{k+1}) \leq  \varphi(x_{k}) - \frac{\beta_{k+1}}{2} \|\Delta x_{k+1}\|^2. 
    \end{align*}
    This proves our statement. \hfill\qed
\end{proof}

\begin{lemma} \label{bound_subgradient}
Let \((x_k)_{k \geq 0}\) be generated by Monotone LiBCoD \ref{alg:libcod}. If \cref{ass:1} holds on a compact set to which the iterates belong, then, for all \(k \geq 0\), we have
\begin{equation}\label{bounde_gradient1}
    \begin{split}
     \dist\left(0, \partial_{i_k} \varphi (x_{k+1})  \right)
     & \leq \left( L^f_{i_k} + L^F_{i_k} \sqrt{2L_h} \sqrt{ \varphi(x_0) - \varphi^*} + \beta_{k+1}\right)  \|\Delta x_{k+1}\|
     \\
     \MoveEqLeft[-1] + \frac{L_h M^{F}_{i_k}L^{F}_{i_k}}{2} \|\Delta x_{k+1}\|^2,
    \end{split}
\end{equation}
where $\|\nabla_{i_k}F(x_k)\| \leq M^{F}_{i_k}$.% \textcolor{red}{and $\partial \varphi(x)$ denotes the Mordukhovich (aka.~limiting) subdifferential of $\varphi$ at $x$.} 
\end{lemma}

\begin{proof}
    By the optimality condition corresponding to the $s_{k+1}$ determining subproblem on Line 6 of Monotone LiBCoD \ref{alg:libcod}, we have
    \[
        -\nabla_{i_k} f(x_{k})-\nabla_{i_k} F(x_{k})^T \nabla h\left( l^{i_k}_F(s_{k+1};x_k)\right)-\beta_{k+1}(x_{k+1}-x_{k})\in \partial g_{i_k}(s_{k+1}).
    \]
    It then follows, by exploiting the definition of $\varphi$ and the properties of the derivative, that
    \begin{align*}
        &\dist\left(0,\partial_{i_k} \varphi (x_{k+1})\right)\\
        &=  \dist\left(-\nabla_{i_k} f(x_{k+1}) - \nabla_{i_k} F(x_{k+1})^T \nabla h \left( F(x_{k+1})\right) , \partial g_{i_k}(s_{k+1})\right)\\
        & \leq  \Bigg \|\nabla_{i_k} f(x_{k+1}) - \nabla_{i_k} f(x_k) + \Big(\nabla_{i_k} F(x_{k+1}) - \nabla_{i_k} F(x_{k})\Big)^T\nabla h\left(  F(x_{k+1})\right)  \\
        & -\beta_{k+1}\Delta x_{k+1} +\nabla_{i_k} F(x_{k})^T\left( \nabla h \left( F(x_{k+1}) \right)-\nabla h\left( l^{i_k}_F(s_{k+1};x_k)\right)\right) \Bigg\|.
    \end{align*}
    Using the triangle inequality, we further get
    \begin{equation}
        \label{eq:lem2-bndsub}
        \begin{split}
            &
            \dist\left(0, \partial_{i_k} \varphi (x_{k+1}) \right) \leq  \|\nabla_{i_k} f(x_{k+1})-\nabla_{i_k} f(x_k)\|
            \\
            \MoveEqLeft[-1] + \left\|\nabla h\left( F(x_{k+1})\right)\right\|\left\|\nabla_{i_k} F(x_{k+1}) - \nabla_{i_k} F(x_{k})\right\|+\beta_{k+1}\|\Delta x_{k+1}\|
            \\
            \MoveEqLeft[-1]
            +\|{\nabla_{i_k} F(x_{k})}\|\left\| \nabla h \left( F(x_{k+1}) \right)-\nabla h\left( l^{i_k}_F(s_{k+1};x_k)\right)\right\|
            \\
            &
            {\overset{{\text{Ass. } \ref{ass:1}}}{\leq}} \left(L^f_{i_k}+\left\|\nabla h\left( F(x_{k+1})\right)\right\| L^F_{i_k} +\beta_{k+1}\right)\|\Delta x_{k+1}\|
            + \frac{L_h M^{F}_{i_k}L^{F}_{i_k}}{2} \|\Delta x_{k+1}\|^2
            \\
            &\leq \left( L^f_{i_k} + L^F_{i_k} \sqrt{2L_h \left(h(F(x_k)) \!-\! h^*\right)} + \beta_{k+1}\right) \|\Delta x_{k+1}\|  + \frac{L_h M^{F}_{i_k}L^{F}_{i_k}}{2} \|\Delta x_{k+1}\|^2
            \\
            &
            \leq  \left( L^f_{i_k} + L^F_{i_k} \sqrt{2L_h \left(\varphi(x_k) - \varphi^*\right)} + \beta_{k+1}\right)  \|\Delta x_{k+1}\| + \frac{L_h M^{F}_{i_k}L^{F}_{i_k}}{2} \|\Delta x_{k+1}\|^2
            \\
            &
            \leq  \left( L^f_{i_k} + L^F_{i_k} \sqrt{2L_h \left(\varphi(x_0) - \varphi^*\right)} + \beta_{k+1}\right)  \|\Delta x_{k+1}\| + \frac{L_h M^{F}_{i_k}L^{F}_{i_k}}{2} \|\Delta x_{k+1}\|^2
             \\
            &
            \leq  \left( L^f + L^F \sqrt{2L_h \left(\varphi(x_0) - \varphi^*\right)} + \bar{\beta}\right)  \|\Delta x_{k+1}\| + \frac{L_h M^{F}L^{F}}{2} \|\Delta x_{k+1}\|^2,
        \end{split}
    \end{equation}
        where the third inequality follows from the following relation for $u= F(x_{k}) \in \mathbb{R}^m$, and $v = u - \frac{1}{L_h} \nabla h(u)$
    \[
        h^* - h(u) \leq h(v) - h(u)
        \leq \langle \nabla h(u), v - u \rangle + \frac{L_ h}{2} \norm{v - u}^2 = -\frac{1}{2L_h} \norm{\nabla h(u)}^2,
    \]
    and $M^F:=\max_{i\in\{1, \ldots, n_{\text{block}}\}} M^F_{i}$, and the fourth inequality follows from the fact that \( \varphi(x) = f(x) + h(F(x)) + g(x) \) and \( \varphi^* = h^* + f^* + g^* \), where \( h^*, g^*, \) and \( f^* \) are the lower bounds of \( h(x) \), \( g(x) \), and \( f(x) \), respectively, as defined in \cref{ass:1}.
    This proves our claim. \hfill\qed
\end{proof}

\begin{proposition}[Asymptotic convergence]
    \label{propos:asymtotic:monotone}
    Let $(x_k)_{k\geq 0}$ be generated by Monotone LiBCoD \ref{alg:libcod}. If \cref{ass:1} holds on a compact set to which the iterates belong, then we have 
    \[
        \lim_{k\to \infty} \E \left[\dist(0, \partial\varphi(x_{k})) \right] = 0,
    \]
\end{proposition}

\begin{proof}
     Let $k\geq0$. From Monotone LiBCoD \ref{alg:libcod}, we have
    \begin{align*}
        \frac{\beta_{\min}}{2}\|x_{k+1} - x_k\|^{2}\leq \frac{\beta_{k+1}}{2}\|x_{k+1} - x_k\|^{2}   \leq  \varphi(x_k) - \varphi(x_{k+1}).
    \end{align*}
    Taking the expectation, we obtain
    \begin{align*}
        \frac{\beta_{\min}}{2} \E\left[\|x_{k+1} - x_k\|^{2}\right]  \leq  \E\left[\varphi(x_k)\right] - \E[\varphi(x_{k+1})].
    \end{align*}
    Summing the above inequality from $k=0$ to $K\geq 0$, we get
    \begin{align*}
        \frac{\beta_{\min}}{2 }\sum_{k=0}^{K}\E\left[\|x_{k+1} - x_k\|^{2}\right]  &\leq  \sum_{k=0}^{K}\left(\E\left[\varphi(x_k)\right] - \E[\varphi(x_{k+1})]\right) \\
        & = \E\left[\varphi(x_0)\right] - \E[\varphi(x_{K+1})]\\
        & \leq \varphi(x_0) - \varphi^*.
        \end{align*}
    Taking the limit $K \to \infty$, we get
    \begin{align*}
        \frac{\beta_{\min}}{2 }\sum_{k=0}^{\infty}\E\left[\|x_{k+1} - x_k\|^{2}\right]  \leq \varphi(x_0) - \varphi^* < \infty.
    \end{align*}
    Since $\beta_{\min} > 0$, it follows that
    \begin{equation}\label{zero_limit}
        \lim_{k\to\infty}{\E\left[\|x_{k+1} - x_{k}\|^2\right]}=0 \quad \text{ and } \quad \lim_{k\to\infty}{\E\left[\|x_{k+1} - x_{k}\|\right]}=0, 
    \end{equation}
    where the limit on the right-hand side of \eqref{zero_limit} follows from Jensen's inequality. For simplicity, we denote $\E_k[\cdot] =  \E[\cdot|x_k]$.  On the other, using \ref{bound_subgradient}, we deduce
      \allowdisplaybreaks
    \begin{equation}
        \label{subgrad_bound_asymp}
        \begin{split}
            &\dist(0, \partial\varphi(x_{k+1}))
            \leq
            \sum_{i=1}^{n_{\text{block}}}{\dist \left(0, \partial_i\varphi(x_{k+1})\right)}
            \\
            &
            \leq
            \frac{1}{p_{\min}}\sum_{i=1}^{n_{\text{block}}}{p_i \; \dist \left(0, \partial_{i_k}\varphi(x_{k+1})\right)}
            \\
            &
            = \frac1p_{\min}  \E_{k}\left[\dist \left(0, \partial_{i_k}\varphi(x_{k+1})\right)\right]
            \\
            &
            \overset{\eqref{bounde_gradient1}}{\leq }
            \frac1p_{\min}\E_{k}\left[  \left( L^f_{i_k} + L^F_{i_k} \sqrt{2L_h} \sqrt{ \left(\varphi(x_0) - \varphi^*\right)} + \beta_{k+1}\right)  \|\Delta x_{k+1}\| \right.\\
            \MoveEqLeft[-1] \left. + \frac{L_h M^{F}_{i_k}L^{F}_{i_k}}{2} \|\Delta x_{k+1}\|^2 \right]
            \\
            &
            \overset{\eqref{bar_gamma}}{\leq}
            \frac{1}{p_{\min}} \left( L^f + L^F \sqrt{2L_h} \sqrt{ \left(\varphi(x_0) - \varphi^*\right)} + \bar{\beta} \right)  \E_{k}\left[\|\Delta x_{k+1}\|\right]\\
             \MoveEqLeft[-1] + \frac{L_h M^F L^{F}}{2p_{\min}} \E_{k}\left[\|\Delta x_{k+1}\|^2 \right].
        \end{split}
    \end{equation}
  Taking expectation in \eqref{subgrad_bound_asymp}, we obtain
    \begin{align*}
            \E\left[\dist(0, \partial\varphi(x_{k+1}))\right] 
            %&\leq             \frac{1}{p_{\min}} \left( L^f + L^F \sqrt{2L_h} \sqrt{ \left(\varphi(x_0) - \varphi^*\right)} + \bar{\beta} \right)  \E\left[\E_{k}\left[\|\Delta x_{k+1}\|\right]\right] +  \frac{L_h M^F L^{F}}{2p_{\min}} \E\left[\E_{k}\left[\|\Delta x_{k+1}\|^2 \right]\right] \\
            &\leq
            \frac{1}{p_{\min}} \left( L^f \!+\! L^F \sqrt{2L_h} \sqrt{ \left(\varphi(x_0) \!-\! \varphi^*\right)} + \bar{\beta} \right)  \E\left[\|\Delta x_{k+1}\|\right]\\
             \MoveEqLeft[-1] +  \frac{L_h M^F L^{F}}{2p_{\min}} \E\left[\|\Delta x_{k+1}\|^2 \right]
    \end{align*}
    Passing to the limit and using \eqref{zero_limit}, we get
      $  \lim_{k\to \infty} \E\left[\dist(0, \partial\varphi(x_{k})) \right] = 0.$ \hfill\qed
\end{proof}

\begin{proof}
    From \cref{propos:asymtotic:monotone}, we know that  $\E\left[\dist(0, \partial\varphi(x_{k})) \right] \to 0$ as $k\to \infty$. Let $\epsilon>0$ and let $N\geq 0$ be the first integer such that
    \begin{equation}
    \E\left[\dist(0, \partial\varphi(x_{N+1})) \right] \leq \epsilon.
    \end{equation}
    Using  \eqref{bounde_gradient1} from  \cref{bound_subgradient}, it follows that at each iteration, $k \in [0:N]$, we encounter one of the following two cases:\\
    \noindent \textit{Case 1: } If the following holds
    \[
        \left(L^f+ L^F \sqrt{2L_h} \sqrt{\varphi(x_0)- \varphi^*} + \bar{\beta}\right)\|\Delta x_{k+1}\|\geq \frac{L_h M^F L^F}{2}\|\Delta x_{k+1}\|^2,
    \]
    then we get
    \begin{align} \label{case1}
        & \dist^2\left(0, \partial_{i_k} \varphi (x_{k+1}) \right) \leq 2 \left(L^f+ L^F \sqrt{2L_h} \sqrt{\varphi(x_0)- \varphi^*} + \bar{\beta}\right)^2\|\Delta x_{k+1}\|^2 \nonumber\\
        &\overset{\eqref{decrease}}{\leq} \frac{4\left(L^f+ L^F \sqrt{2L_h} \sqrt{\varphi(x_0)- \varphi^*} + \bar{\beta}\right)^2}{\beta_{k+1}}\left(\varphi(x_{k}) - \varphi(x_{k+1})\right).
    \end{align}
    \noindent \textit{Case 2: } Otherwise,  the following is valid 
    \[
        \left(L^f+ L^F \sqrt{2L_h} \sqrt{\varphi(x_0)- \varphi^*} + \bar{\beta}\right)\|\Delta x_{k+1}\|< \frac{L_h M^F L^F}{2}\|\Delta x_{k+1}\|^2,
    \]
    which yields
    \begin{equation}\label{case2}
        \dist\left(0, \partial_{i_k} \varphi (x_{k+1}) \right) \leq L_h M^F L^F \|\Delta x_{k+1}\|^2\overset{\eqref{decrease}}{\leq} \frac{2 L_h M^F L^F}{\beta_{k+1}}\left(\varphi(x_{k}) - \varphi(x_{k+1})\right).
    \end{equation}
    Define $\mathcal{I}_1$ as the set of iterations $k \in [0:N-1]$ at which   \textit{Case 1} holds, and  $\mathcal{I}_2$ as the set of iterations $k\in [0:N-1]$ at which   \textit{Case 2} holds. Clearly: $N=|\mathcal{I}_1|+|\mathcal{I}_2|+1$. We first derive an upper bound for $|\mathcal{I}_1|$.  Let $k \in \mathcal{I}_1$, we have
    \allowdisplaybreaks
    \begin{equation}
        \label{criticality1_squared}
        \begin{split}
        &\dist^2(0, \partial\varphi(x_{k+1}))
        =
        \sum_{i=1}^{n_{\text{block}}}{\dist^2 \left(0, \partial_i\varphi(x_{k+1})\right)}
        \\
        &
        \leq
        \frac{1}{p_{\min}}\sum_{i=1}^{n_{\text{block}}}{p_i \; \dist^2 \left(0, \partial_i\varphi(x_{k+1})\right)}
        \\
        &
        = \frac1p_{\min}  \E_{k}\left[\dist^2 \left(0, \partial_{i_k}\varphi(x_{k+1})\right)\right]
        \\
        &
        \overset{\eqref{case1} }{\leq }
        \frac1p_{\min}  \frac{4\left(L^f+ L^F \sqrt{2L_h} \sqrt{\varphi(x_0)- \varphi^*} + \bar{\beta}\right)^2}{\beta_{k+1}}      \E_{k} \left[\varphi(x_{k}) - \varphi(x_{k+1}) \right]
        \\
        &
        \leq
        \frac{4\left(L^f+ L^F \sqrt{2L_h} \sqrt{\varphi(x_0)- \varphi^*} + \bar{\beta}\right)^2}{p_{\min} \beta_{\min}}      
        \left(\varphi(x_k) - \E_{k} [\varphi(x_{k+1})]\right).
        \end{split}
    \end{equation}
    Taking the expectation in the inequality \eqref{criticality1_squared} and summing it over $\mathcal{I}_1$ yields
    \begin{align*}
        |\mathcal{I}_1|\epsilon^2  & < \sum_{k\in\mathcal{I}_1} \left(\E\left[\dist(0, \partial\varphi(x_{k+1}))\right]\right)^2\leq \sum_{k\in\mathcal{I}_1} \E\left[\dist^2(0, \partial\varphi(x_{k+1}))\right]  \\
        & \leq  \sum_{k\in\mathcal{I}_1}  \frac{4\left(L^f+ L^F \sqrt{2L_h} \sqrt{\varphi(x_0)- \varphi^*} + \bar{\beta}\right)^2}{p_{\min} \beta_{\min}}      
        \E\left[\varphi(x_k) - \E_{k} [\varphi(x_{k+1})]\right] \\
        & = \frac{4\left(L^f+ L^F \sqrt{2L_h} \sqrt{\varphi(x_0)- \varphi^*} + \bar{\beta}\right)^2}{p_{\min} \beta_{\min}}   \sum_{k\in\mathcal{I}_1}      
        \left(\E\left[\varphi(x_k)\right] - \E [\varphi(x_{k+1})]\right)\\
        & \overset{\eqref{decrease}}{\leq}  \frac{4\left(L^f+ L^F \sqrt{2L_h} \sqrt{\varphi(x_0)- \varphi^*} + \bar{\beta}\right)^2}{p_{\min} \beta_{\min}}   \sum_{k=0}^{N-1}      
        \left(\E\left[\varphi(x_k)\right] - \E [\varphi(x_{k+1})]\right)  \\
        & = \frac{4\left(L^f+ L^F \sqrt{2L_h} \sqrt{\varphi(x_0)- \varphi^*} + \bar{\beta}\right)^2}{p_{\min} \beta_{\min}}  \left(\E[\varphi(x_0)] - \E[\varphi(x_N)]\right)  \\ 
        & \leq \frac{4\left(L^f+ L^F \sqrt{2L_h} \sqrt{\varphi(x_0)- \varphi^*} + \bar{\beta}\right)^2}{p_{\min} \beta_{\min}}  \left(\varphi(x_0) - \varphi^*\right) .
    \end{align*}
    Thus, we have: $|\mathcal{I}_1|< \frac{4\left(L^f+ L^F \sqrt{2L_h} \sqrt{\varphi(x_0)- \varphi^*} + \bar{\beta}\right)^2}{p_{\min} \beta_{\min} \epsilon^2}  \left(\varphi(x_0) - \varphi^*\right)$. Similarly, we derive an upper bound for $|\mathcal{I}_2|$. Let $k\in \mathcal{I}_2$, we have
    \allowdisplaybreaks
    \begin{equation}
        \label{criticality1}
        \begin{split}
        \dist(0, \partial\varphi(x_{k+1}))
        &
        \leq
        \sum_{i=1}^{n_{\text{block}}}{\dist(0, \partial_i\varphi(x_{k+1}))}
        \\
        &
        \leq
        \frac{1}{p_{\min}}\sum_{i=1}^{n_{\text{block}}}{p_i \; \dist(0, \partial\varphi_i(x_{k+1}))}
        \\
        &
        = \frac1p_{\min}  \E_{k}\left[\dist(0, \partial\varphi_{i_k}(x_{k+1}))\right]
        \\
        &
        \overset{\eqref{case2} }{\leq }
        \frac1p_{\min}  \frac{2 L_h M^F L^F}{\beta_{k+1}}      \E_{k} \left[\varphi(x_{k}) - \varphi(x_{k+1}) \right]
        \\
        &
        \leq
         \frac{2 L_h M^F L^F}{p_{\min} \beta_{\min}}      
        \left(\varphi(x_k) - \E_{k} [\varphi(x_{k+1})]\right).
        \end{split}
    \end{equation}
    Taking the expectation in the inequality \eqref{criticality1} and summing it over $\mathcal{I}_2$ yields
    \begin{align*}
        &  |\mathcal{I}_2|\epsilon  < \sum_{k\in\mathcal{I}_2} \E\left[\dist(0, \partial\varphi(x_{k+1}))\right]  \leq  \sum_{k\in\mathcal{I}_2} \frac{2 L_h M^F L^F}{p_{\min} \beta_{\min}} \E\left[\varphi(x_k) - \E_{k} [\varphi(x_{k+1})]\right]\\
        &  = \frac{2 L_h M^F L^F}{p_{\min} \beta_{\min}} \sum_{k\in\mathcal{I}_2}  \left(\E\left[\varphi(x_k)\right] - \E [\varphi(x_{k+1})]\right)\\
        & \overset{\eqref{decrease}}{\leq}  \frac{2 L_h M^F L^F}{p_{\min} \beta_{\min}} \sum_{k=0}^{N-1}  \left(\E\left[\varphi(x_k)\right] - \E [\varphi(x_{k+1})]\right)\\
        & \leq  \frac{2 L_h M^F L^F}{p_{\min} \beta_{\min}}   \left(\E\left[\varphi(x_0)\right] - \E [\varphi(x_{N+1})]\right)\leq \frac{2 L_h M^F L^F}{p_{\min} \beta_{\min}}   \left(\varphi(x_0) - \varphi^*\right).
    \end{align*}
    Therefore, we obtain: $|\mathcal{I}_2|< \frac{2 L_h M^F L^F}{p_{\min} \beta_{\min} \epsilon}   \left(\varphi(x_0) - \varphi^*\right) $.  Consequently, we obtain
    \[
        N \leq  \left(\frac{4\left(L^f+ L^F \sqrt{2L_h} \sqrt{\varphi(x_0)- \varphi^*} + \bar{\beta}\right)^2}{p_{\min} \beta_{\min} \epsilon^2}  + \frac{2 L_h M^F L^F}{p_{\min} \beta_{\min} \epsilon} \right)\left(\varphi(x_0) - \varphi^*\right).
        \]
    This proves our claim. \hfill\qed
\end{proof}

