\begin{proof}
    From \cref{propos:asymtotic:monotone}, we know that  $\E\left[\dist(0, \partial\varphi(x_{k})) \right] \to 0$ as $k\to \infty$. Let $\epsilon>0$ and let $N\geq 0$ be the first integer such that
    \begin{equation}
    \E\left[\dist(0, \partial\varphi(x_{N+1})) \right] \leq \epsilon.
    \end{equation}
    Using  \eqref{bounde_gradient1} from  \cref{bound_subgradient}, it follows that at each iteration, $k \in [0:N]$, we encounter one of the following two cases:\\
    \noindent \textit{Case 1: } If the following holds
    \[
        \left(L^f+ L^F \sqrt{2L_h} \sqrt{\varphi(x_0)- \varphi^*} + \bar{\beta}\right)\|\Delta x_{k+1}\|\geq \frac{L_h M^F L^F}{2}\|\Delta x_{k+1}\|^2,
    \]
    then we get
    \begin{align} \label{case1}
        & \dist^2\left(0, \partial_{i_k} \varphi (x_{k+1}) \right) \leq 2 \left(L^f+ L^F \sqrt{2L_h} \sqrt{\varphi(x_0)- \varphi^*} + \bar{\beta}\right)^2\|\Delta x_{k+1}\|^2 \nonumber\\
        &\overset{\eqref{decrease}}{\leq} \frac{4\left(L^f+ L^F \sqrt{2L_h} \sqrt{\varphi(x_0)- \varphi^*} + \bar{\beta}\right)^2}{\beta_{k+1}}\left(\varphi(x_{k}) - \varphi(x_{k+1})\right).
    \end{align}
    \noindent \textit{Case 2: } Otherwise,  the following is valid 
    \[
        \left(L^f+ L^F \sqrt{2L_h} \sqrt{\varphi(x_0)- \varphi^*} + \bar{\beta}\right)\|\Delta x_{k+1}\|< \frac{L_h M^F L^F}{2}\|\Delta x_{k+1}\|^2,
    \]
    which yields
    \begin{equation}\label{case2}
        \dist\left(0, \partial_{i_k} \varphi (x_{k+1}) \right) \leq L_h M^F L^F \|\Delta x_{k+1}\|^2\overset{\eqref{decrease}}{\leq} \frac{2 L_h M^F L^F}{\beta_{k+1}}\left(\varphi(x_{k}) - \varphi(x_{k+1})\right).
    \end{equation}
    Define $\mathcal{I}_1$ as the set of iterations $k \in [0:N-1]$ at which   \textit{Case 1} holds, and  $\mathcal{I}_2$ as the set of iterations $k\in [0:N-1]$ at which   \textit{Case 2} holds. Clearly: $N=|\mathcal{I}_1|+|\mathcal{I}_2|+1$. We first derive an upper bound for $|\mathcal{I}_1|$.  Let $k \in \mathcal{I}_1$, we have
    \allowdisplaybreaks
    \begin{equation}
        \label{criticality1_squared}
        \begin{split}
        &\dist^2(0, \partial\varphi(x_{k+1}))
        =
        \sum_{i=1}^{n_{\text{block}}}{\dist^2 \left(0, \partial_i\varphi(x_{k+1})\right)}
        \\
        &
        \leq
        \frac{1}{p_{\min}}\sum_{i=1}^{n_{\text{block}}}{p_i \; \dist^2 \left(0, \partial_i\varphi(x_{k+1})\right)}
        \\
        &
        = \frac1p_{\min}  \E_{k}\left[\dist^2 \left(0, \partial_{i_k}\varphi(x_{k+1})\right)\right]
        \\
        &
        \overset{\eqref{case1} }{\leq }
        \frac1p_{\min}  \frac{4\left(L^f+ L^F \sqrt{2L_h} \sqrt{\varphi(x_0)- \varphi^*} + \bar{\beta}\right)^2}{\beta_{k+1}}      \E_{k} \left[\varphi(x_{k}) - \varphi(x_{k+1}) \right]
        \\
