    \begin{align*}
        |\mathcal{I}_1|\epsilon^2  & < \sum_{k\in\mathcal{I}_1} \left(\E\left[\dist(0, \partial\varphi(x_{k+1}))\right]\right)^2\leq \sum_{k\in\mathcal{I}_1} \E\left[\dist^2(0, \partial\varphi(x_{k+1}))\right]  \\
